using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using UAF.Application.Common.Abstractions;using UAF.Application.Features.Admissions.Abstractions;using UAF.Application.Features.AcademicStructure.Abstractions;using UAF.Application.Features.AcademicCatalog.Abstractions;using UAF.Application.Features.Students.Abstractions;using UAF.Application.Features.CourseOfferings.Abstractions;using UAF.Application.Features.Fees.Abstractions;using UAF.Application.Features.Employees.Abstractions;using UAF.Application.Features.Attendance.Abstractions;using UAF.Application.Features.Examinations.Abstractions;using UAF.Application.Features.Grading.Abstractions;using UAF.Application.Features.Transcripts.Abstractions;using UAF.Application.Features.Timetable.Abstractions;using UAF.Application.Features.Authentication.Abstractions;using UAF.Application.Features.Notifications;using UAF.Application.Features.Workflows;using UAF.Application.Features.Documents;using UAF.Infrastructure.Identity;using UAF.Infrastructure.Persistence;using UAF.Infrastructure.Persistence.Repositories;using UAF.Infrastructure.Files;using UAF.Infrastructure.Documents;using UAF.Infrastructure.Persistence.Interceptors;using UAF.Infrastructure.Notifications;
namespace UAF.Infrastructure;
public static class DependencyInjection{
 public static IServiceCollection AddInfrastructure(this IServiceCollection services,IConfiguration configuration){
 ArgumentNullException.ThrowIfNull(services);ArgumentNullException.ThrowIfNull(configuration);var connection=configuration.GetConnectionString("UafDatabase");if(string.IsNullOrWhiteSpace(connection))throw new InvalidOperationException("Connection string 'UafDatabase' is required.");
 var redis=configuration.GetConnectionString("Redis");if(!string.IsNullOrWhiteSpace(redis))services.AddStackExchangeRedisCache(o=>{o.Configuration=redis;o.InstanceName=configuration["Redis:InstanceName"]??"UAF:";});
 services.AddOptions<JwtOptions>().Bind(configuration.GetSection(JwtOptions.SectionName)).Validate(o=>!string.IsNullOrWhiteSpace(o.Issuer),"Jwt:Issuer required.").Validate(o=>!string.IsNullOrWhiteSpace(o.Audience),"Jwt:Audience required.").Validate(o=>!string.IsNullOrWhiteSpace(o.SigningKey)&&System.Text.Encoding.UTF8.GetByteCount(o.SigningKey)>=32,"Jwt:SigningKey must contain at least 32 bytes.").Validate(o=>o.AccessTokenMinutes is >=1 and <=1440,"Invalid access token lifetime.").Validate(o=>o.RefreshTokenDays is >=1 and <=90,"Invalid refresh token lifetime.").ValidateOnStart();
 services.AddOptions<AdmissionDocumentStorageOptions>().Bind(configuration.GetSection(AdmissionDocumentStorageOptions.SectionName)).Validate(o=>!string.IsNullOrWhiteSpace(o.RootPath),"AdmissionDocumentStorage:RootPath required.").ValidateOnStart();
 services.Configure<NotificationDeliveryOptions>(configuration.GetSection(NotificationDeliveryOptions.SectionName));
 services.AddHttpContextAccessor();services.AddScoped<UafCommandMonitoringInterceptor>();services.AddScoped<UafSaveChangesAuditInterceptor>();services.AddScoped<UafCentralAuditInterceptor>();
 services.AddDbContext<UafDbContext>((sp,o)=>o.UseSqlServer(connection).AddInterceptors(sp.GetRequiredService<UafCommandMonitoringInterceptor>(),sp.GetRequiredService<UafSaveChangesAuditInterceptor>(),sp.GetRequiredService<UafCentralAuditInterceptor>()));
 services.AddHostedService<IdempotencyCleanupService>();
 services.AddIdentityCore<ApplicationUser>(o=>{o.User.RequireUniqueEmail=true;o.Password.RequiredLength=12;o.Password.RequireDigit=true;o.Password.RequireLowercase=true;o.Password.RequireUppercase=true;o.Password.RequireNonAlphanumeric=true;o.Lockout.AllowedForNewUsers=true;o.Lockout.MaxFailedAccessAttempts=5;o.Lockout.DefaultLockoutTimeSpan=TimeSpan.FromMinutes(15);}).AddRoles<IdentityRole<Guid>>().AddEntityFrameworkStores<UafDbContext>().AddSignInManager();
 services.AddSingleton<IAdmissionDocumentStorage,LocalAdmissionDocumentStorage>();services.AddSingleton<IFileStorage>(sp=>sp.GetRequiredService<IAdmissionDocumentStorage>());
 services.AddScoped<IJwtTokenGenerator,JwtTokenGenerator>();services.AddScoped<IAuthenticationService,IdentityAuthenticationService>();services.AddScoped<IUnitOfWork>(sp=>sp.GetRequiredService<UafDbContext>());
 services.AddScoped<IAdmissionApplicationRepository,AdmissionApplicationRepository>();services.AddScoped<IAdmissionWorkflowRepository,AdmissionWorkflowRepository>();services.AddScoped<IAdmissionDocumentRepository,AdmissionDocumentRepository>();services.AddScoped<IAcademicStructureRepository,AcademicStructureRepository>();services.AddScoped<IAcademicCatalogRepository,AcademicCatalogRepository>();services.AddScoped<IStudentRepository,StudentRepository>();services.AddScoped<ICourseOfferingRepository,CourseOfferingRepository>();services.AddScoped<IFeeRepository,FeeRepository>();services.AddScoped<IEmployeeRepository,EmployeeRepository>();services.AddScoped<IAttendanceRepository,AttendanceRepository>();services.AddScoped<IAttendanceReportingRepository,AttendanceReportingRepository>();services.AddScoped<IExaminationRepository,ExaminationRepository>();services.AddScoped<IGradingRepository,GradingRepository>();services.AddScoped<IGradeAppealRepository,GradeAppealRepository>();services.AddScoped<IGradeRevisionRepository,GradeRevisionRepository>();services.AddScoped<ITranscriptRepository,TranscriptRepository>();services.AddScoped<ITimetableRepository,TimetableRepository>();
 services.AddScoped<INotificationRepository,NotificationRepository>();services.AddScoped<IWorkflowRepository,WorkflowRepository>();services.AddSingleton<IEmailSender,SmtpEmailSender>();services.AddHttpClient<ISmsSender,HttpSmsSender>();services.AddSingleton<ITranscriptPdfGenerator,QuestPdfTranscriptGenerator>();services.AddSingleton<IUniversityDocumentPdfGenerator,QuestPdfUniversityDocumentGenerator>();return services;
 }}
